  if(db_getsession('DB_instit') == 1 || db_getsession('DB_instit') == 20 ||
      db_getsession('DB_instit') == 25 || db_getsession('DB_instit') == 30 || 
          db_getsession('DB_instit') == 35 || db_getsession('DB_instit') == 40 ||
              db_getsession('DB_instit') == 45 || db_getsession('DB_instit') == 55 || 
                  db_getsession('DB_instit') == 65 || db_getsession('DB_instit') == 75 || 
                      db_getsession('DB_instit') == 80) {

    $h80_db_cadattdinamicovalorgrupo = $_POST["h80_db_cadattdinamicovalorgrupo"];

    if (!empty($h80_db_cadattdinamicovalorgrupo)) {
          $plugin = new Plugin(null, 'pontoeletronicoassentamentoferias');
          $configuracao = PluginService::getPluginConfig($plugin);
          $tipoAssentamento = TipoAssentamentoRepository::getInstance()->getInstanciaPorTipo(current($configuracao));

          if(count($configuracao) == 0) {
              throw new BusinessException('Tipo de Asssentamento não configurado no plugin PontoEletronicoAssentamentoFerias.');
          }

          $periodoAquisitivoInicio = new DBDate($_POST["r30_perai"]);
          $periodoAquisitivoFim = new DBDate($_POST["r30_peraf"]);

          $periodoGozoInicio = new DBDate($r30_peri);
          $periodoGozoFim = new DBDate($r30_perf);

          $historicoPeriodoAquisitivo  = "referente ao período aquisitivo de {$periodoAquisitivoInicio->getDate(DBDate::DATA_PTBR)}";
          $historicoPeriodoAquisitivo .= " à {$periodoAquisitivoFim->getDate(DBDate::DATA_PTBR)}";

          $oAssentamento = new Assentamento();
          $oAssentamento->setMatricula($pessoal[0]["r01_regist"]);
          $oAssentamento->setTipoAssentamento($tipoAssentamento->getSequencial());
          $oAssentamento->setHistorico("Gozo de Férias {$historicoPeriodoAquisitivo}");
          $oAssentamento->setPercentual("0");
          $oAssentamento->setLoginUsuario(db_getsession("DB_id_usuario"));
          $oAssentamento->setDataLancamento(date("Y-m-d", db_getsession("DB_datausu")));
          $oAssentamento->setConvertido("false");
          $oAssentamento->setDias(isset($r30_ndias) ? $r30_ndias : $ndiassaldo);
          $oAssentamento->setDataConcessao($periodoGozoInicio);
          $oAssentamento->setDataTermino($periodoGozoFim);
          $oAssentamento->setDias(DBDate::getIntervaloEntreDatas($periodoGozoInicio, $periodoGozoFim)->d + 1);

          AssentamentoRepository::persist($oAssentamento);

          /**
          * Incluindo a marcação das 3 justificativas
          */
          $periodosJustificativa = array(1,2,3);
          foreach ($periodosJustificativa as $periodo) {

              $oDaoAssentamentoJustificativa = new cl_assentamentojustificativaperiodo;
              $oDaoAssentamentoJustificativa->rh206_codigo  = $oAssentamento->getCodigo();
              $oDaoAssentamentoJustificativa->rh206_periodo = $periodo;

              $oDaoAssentamentoJustificativa->incluir();

              if($oDaoAssentamentoJustificativa->erro_status == '0') {
                  throw new DBException($oDaoAssentamentoJustificativa->erro_msg);
              }
          }

          $oDaoAssentaAttr = new cl_assentadb_cadattdinamicovalorgrupo();
          $oDaoAssentaAttr->h80_assenta = $oAssentamento->getCodigo();
          $oDaoAssentaAttr->h80_db_cadattdinamicovalorgrupo = $h80_db_cadattdinamicovalorgrupo;
          $oDaoAssentaAttr->incluir($oAssentamento->getCodigo(), $h80_db_cadattdinamicovalorgrupo);

          if ($oDaoAssentaAttr->erro_status == "0") {
              throw new Exception($oDaoAssentaAttr->erro_msg);
          }

          $oDaoAssentamentoFuncional = new cl_assentamentofuncional();
          $oDaoAssentamentoFuncional->rh193_assentamento_funcional = $oAssentamento->getCodigo();
          $oDaoAssentamentoFuncional->rh193_assentamento_efetividade = 'null';
          $oDaoAssentamentoFuncional->incluir(null);

          if ($oDaoAssentamentoFuncional->erro_status == '0') {
              throw new BusinessException($oDaoAssentamentoFuncional->erro_msg);
          }

        \ECidade\RecursosHumanos\ESocial\Repository\Assentamento::salvarFormulario($oAssentamento, new DBDate(date('Y-m-d', db_getsession('DB_datausu'))));
    }
}

